// Package semver parses and orders Semantic Versioning 2.0.0 versions.
package semver

import (
	"cmp"
	"fmt"
	"strconv"
	"strings"
)

// Version is a parsed version. Pre and Build hold the dot-separated identifiers.
type Version struct {
	Major, Minor, Patch uint64
	Pre                 []string
	Build               []string
}

// Parse parses s as a SemVer 2.0.0 version.
func Parse(s string) (Version, error) {
	var v Version
	rest, build, hasBuild := strings.Cut(s, "+")
	if hasBuild {
		ids, err := identifiers(build, false)
		if err != nil {
			return Version{}, err
		}
		v.Build = ids
	}
	core, pre, hasPre := strings.Cut(rest, "-")
	if hasPre {
		ids, err := identifiers(pre, true)
		if err != nil {
			return Version{}, err
		}
		v.Pre = ids
	}
	parts := strings.Split(core, ".")
	if len(parts) != 3 {
		return Version{}, fmt.Errorf("semver: %q is not MAJOR.MINOR.PATCH", core)
	}
	for i, field := range []*uint64{&v.Major, &v.Minor, &v.Patch} {
		if !numeric(parts[i]) || leadingZero(parts[i]) {
			return Version{}, fmt.Errorf("semver: invalid number %q", parts[i])
		}
		n, err := strconv.ParseUint(parts[i], 10, 64)
		if err != nil {
			return Version{}, fmt.Errorf("semver: %w", err)
		}
		*field = n
	}
	return v, nil
}

// identifiers splits a prerelease or build section into validated identifiers.
func identifiers(s string, pre bool) ([]string, error) {
	ids := strings.Split(s, ".")
	for _, id := range ids {
		if id == "" || strings.IndexFunc(id, invalid) >= 0 {
			return nil, fmt.Errorf("semver: invalid identifier %q", id)
		}
		if pre && numeric(id) && leadingZero(id) {
			return nil, fmt.Errorf("semver: leading zero in %q", id)
		}
	}
	return ids, nil
}

func invalid(r rune) bool {
	return !(r == '-' || '0' <= r && r <= '9' || 'a' <= r && r <= 'z' || 'A' <= r && r <= 'Z')
}

func numeric(s string) bool {
	return s != "" && strings.Trim(s, "0123456789") == ""
}

func leadingZero(s string) bool {
	return len(s) > 1 && s[0] == '0'
}

// String formats v in SemVer syntax.
func (v Version) String() string {
	s := fmt.Sprintf("%d.%d.%d", v.Major, v.Minor, v.Patch)
	if len(v.Pre) > 0 {
		s += "-" + strings.Join(v.Pre, ".")
	}
	if len(v.Build) > 0 {
		s += "+" + strings.Join(v.Build, ".")
	}
	return s
}

// Compare orders a and b by SemVer precedence: -1, 0 or 1.
func Compare(a, b Version) int {
	if c := cmp.Or(cmp.Compare(a.Major, b.Major), cmp.Compare(a.Minor, b.Minor), cmp.Compare(a.Patch, b.Patch)); c != 0 {
		return c
	}
	// A release ranks above any of its prereleases.
	if len(a.Pre) == 0 || len(b.Pre) == 0 {
		return cmp.Compare(len(b.Pre), len(a.Pre))
	}
	for i := 0; i < len(a.Pre) && i < len(b.Pre); i++ {
		if c := compareIdentifier(a.Pre[i], b.Pre[i]); c != 0 {
			return c
		}
	}
	return cmp.Compare(len(a.Pre), len(b.Pre))
}

func compareIdentifier(x, y string) int {
	switch xn, yn := numeric(x), numeric(y); {
	case xn && yn:
		// Without leading zeros, a longer number is larger.
		return cmp.Or(cmp.Compare(len(x), len(y)), strings.Compare(x, y))
	case xn:
		return -1
	case yn:
		return 1
	}
	return strings.Compare(x, y)
}

