package fixture_test

import (
	"cmp"
	"fixture/semver"
	"fixture/textwrap"
	"slices"
	"strings"
	"testing"
	"unicode/utf8"
)

func mustSemver(t *testing.T, s string) semver.Version {
	t.Helper()
	v, err := semver.Parse(s)
	if err != nil {
		t.Fatalf("Parse(%q): %v", s, err)
	}
	return v
}

func TestSemverParseCore(t *testing.T) {
	v := mustSemver(t, "1.20.300")
	if v.Major != 1 || v.Minor != 20 || v.Patch != 300 || len(v.Pre) != 0 || len(v.Build) != 0 {
		t.Fatalf("got %+v", v)
	}
	v = mustSemver(t, "18446744073709551615.0.0")
	if v.Major != 18446744073709551615 {
		t.Fatalf("max uint64: %+v", v)
	}
}

func TestSemverParseIdentifiers(t *testing.T) {
	v := mustSemver(t, "1.0.0-alpha.1+build.5")
	if !slices.Equal(v.Pre, []string{"alpha", "1"}) || !slices.Equal(v.Build, []string{"build", "5"}) {
		t.Fatalf("got %+v", v)
	}
	v = mustSemver(t, "1.0.0+exp.sha.5114f85")
	if len(v.Pre) != 0 || !slices.Equal(v.Build, []string{"exp", "sha", "5114f85"}) {
		t.Fatalf("build only: %+v", v)
	}
	v = mustSemver(t, "1.0.0-x-y-z.--")
	if !slices.Equal(v.Pre, []string{"x-y-z", "--"}) {
		t.Fatalf("hyphens: %+v", v)
	}
}

func TestSemverParseValidEdges(t *testing.T) {
	for _, s := range []string{"0.0.0", "1.2.3-0", "1.2.3-0a", "1.2.3-a.0.b", "1.2.3+001", "1.2.3-rc.1+build.007"} {
		mustSemver(t, s)
	}
}

func TestSemverParseRejects(t *testing.T) {
	for _, s := range []string{
		"", "1", "1.2", "1.2.3.4", "v1.2.3", " 1.2.3", "1.2.3 ", "1.2.-3", "1.2.x",
		"01.2.3", "1.02.3", "1.2.03", "1.2.3-01", "1.2.3-a.00",
		"1.2.3-", "1.2.3+", "1.2.3-a..b", "1.2.3+a..b", "1.2.3-a_b", "1.2.3+a+b", "1.2.3-é",
		"18446744073709551616.0.0",
	} {
		if v, err := semver.Parse(s); err == nil {
			t.Errorf("Parse(%q) = %+v, want error", s, v)
		}
	}
}

func TestSemverStringRoundTrip(t *testing.T) {
	for _, s := range []string{"0.0.0", "1.2.3", "1.2.3-alpha.1", "1.2.3+build.007", "10.20.30-rc.1+x-y.2"} {
		if got := mustSemver(t, s).String(); got != s {
			t.Errorf("String() = %q, want %q", got, s)
		}
	}
	v := semver.Version{Major: 2, Pre: []string{"beta"}, Build: []string{"b1"}}
	if got := v.String(); got != "2.0.0-beta+b1" {
		t.Errorf("built String() = %q", got)
	}
}

func TestSemverComparePrecedenceChain(t *testing.T) {
	chain := []string{
		"1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta", "1.0.0-beta.2",
		"1.0.0-beta.11", "1.0.0-rc.1", "1.0.0", "1.0.1", "1.1.0", "1.9.0", "1.10.0", "2.0.0",
	}
	for i, a := range chain {
		for j, b := range chain {
			want := cmp.Compare(i, j)
			if got := semver.Compare(mustSemver(t, a), mustSemver(t, b)); got != want {
				t.Errorf("Compare(%s, %s) = %d, want %d", a, b, got, want)
			}
		}
	}
}

func TestSemverCompareIdentifiers(t *testing.T) {
	cases := []struct {
		a, b string
		want int
	}{
		{"1.0.0-2", "1.0.0-10", -1},
		{"1.0.0-999", "1.0.0-a", -1},
		{"1.0.0-B", "1.0.0-a", -1},
		{"1.0.0-a-b", "1.0.0-a", 1},
		{"1.0.0-a.b.c", "1.0.0-a.b", 1},
		{"2.0.0-alpha", "1.99.99", 1},
		{"1.0.0+a", "1.0.0+b", 0},
		{"1.0.0-rc.1+a", "1.0.0-rc.1+b.2", 0},
	}
	for _, c := range cases {
		if got := semver.Compare(mustSemver(t, c.a), mustSemver(t, c.b)); got != c.want {
			t.Errorf("Compare(%s, %s) = %d, want %d", c.a, c.b, got, c.want)
		}
	}
}

func wrapCase(t *testing.T, text string, width int, want ...string) {
	t.Helper()
	if got := textwrap.Wrap(text, width); !slices.Equal(got, want) {
		t.Errorf("Wrap(%q, %d) = %q, want %q", text, width, got, want)
	}
}

func TestWrapGreedy(t *testing.T) {
	wrapCase(t, "the quick brown fox jumps over the lazy dog", 10,
		"the quick", "brown fox", "jumps over", "the lazy", "dog")
	wrapCase(t, "aaaa bbbb cccc", 9, "aaaa bbbb", "cccc")
	wrapCase(t, "one two", 80, "one two")
}

func TestWrapCollapsesWhitespace(t *testing.T) {
	wrapCase(t, "  lead\tand   inner \n spaces\ncontinue  ", 12, "lead and", "inner spaces", "continue")
}

func TestWrapCountsRunes(t *testing.T) {
	wrapCase(t, "héllo wörld ñaño", 11, "héllo wörld", "ñaño")
	wrapCase(t, "雪雪 雪 雪雪雪", 4, "雪雪 雪", "雪雪雪")
}

func TestWrapHardSplitsLongWords(t *testing.T) {
	wrapCase(t, "abcdefghij", 4, "abcd", "efgh", "ij")
	wrapCase(t, "ab abcdefghij k", 4, "ab", "abcd", "efgh", "ij k")
	wrapCase(t, "x 雪雪雪雪雪 y", 2, "x", "雪雪", "雪雪", "雪", "y")
	wrapCase(t, "abcdefgh z", 4, "abcd", "efgh", "z")
}

func TestWrapParagraphs(t *testing.T) {
	wrapCase(t, "first para here\n\nsecond", 10, "first para", "here", "", "second")
	wrapCase(t, "a\n \t \n\n\nb\nc\n\n", 10, "a", "", "b c")
	wrapCase(t, "\n\n  \nonly\n\n", 10, "only")
}

func TestWrapEmptyAndTinyWidth(t *testing.T) {
	for _, text := range []string{"", "   ", "\n\n\t\n"} {
		if got := textwrap.Wrap(text, 10); len(got) != 0 {
			t.Errorf("Wrap(%q) = %q, want no lines", text, got)
		}
	}
	wrapCase(t, "ab c", 0, "a", "b", "c")
	wrapCase(t, "ab c", -3, "a", "b", "c")
}

func TestWrapLinesFitWithoutEdgeSpaces(t *testing.T) {
	text := strings.Repeat("lorem ipsum dolor sit amet, consectetur adipiscing elit sed do ", 20)
	for _, width := range []int{1, 7, 13, 40} {
		lines := textwrap.Wrap(text, width)
		if len(lines) == 0 {
			t.Fatalf("width %d: no lines", width)
		}
		for _, line := range lines {
			if line == "" || utf8.RuneCountInString(line) > width || strings.TrimSpace(line) != line || strings.Contains(line, "  ") {
				t.Fatalf("width %d: bad line %q", width, line)
			}
		}
		if strings.Join(strings.Fields(strings.Join(lines, " ")), "") != strings.Join(strings.Fields(text), "") {
			t.Fatalf("width %d: lost text", width)
		}
	}
}

func TestFill(t *testing.T) {
	if got := textwrap.Fill("one two three\n\nfour", 7); got != "one two\nthree\n\nfour" {
		t.Errorf("Fill = %q", got)
	}
	if got := textwrap.Fill("  ", 7); got != "" {
		t.Errorf("Fill(blank) = %q", got)
	}
}

func TestIndent(t *testing.T) {
	cases := []struct{ text, want string }{
		{"a\nb", "> a\n> b"},
		{"a\n\n  \nb\n", "> a\n\n  \n> b\n"},
		{"  x\n\ty\n", ">   x\n> \ty\n"},
		{"", ""},
		{"\n", "\n"},
	}
	for _, c := range cases {
		if got := textwrap.Indent(c.text, "> "); got != c.want {
			t.Errorf("Indent(%q) = %q, want %q", c.text, got, c.want)
		}
	}
}

func TestDedent(t *testing.T) {
	cases := []struct{ text, want string }{
		{"    a\n      b\n    c", "a\n  b\nc"},
		{"\t a\n\t b\n", "a\nb\n"},
		{"  a\n\tb\n", "  a\n\tb\n"},
		{"  a\n    \n\n  b\n", "a\n\n\nb\n"},
		{"   x\n \t\n   y", "x\n\ny"},
		{"a\n  b", "a\n  b"},
		{"", ""},
	}
	for _, c := range cases {
		if got := textwrap.Dedent(c.text); got != c.want {
			t.Errorf("Dedent(%q) = %q, want %q", c.text, got, c.want)
		}
	}
}
